INSERT INTO answer_item (submission_id, step_id, item_id, attribute, value_text, value_number, seq) VALUES ('25171819-dd07-40c1-b058-d149f0d3a157', '10.1', 'excited', 'text', 'Reaching good clients we turn away today, and giving our younger bankers a book to grow.', NULL, 1);
